def verify():
    assert abs(0.7 ** 2 - 0.49) < 1e-12 and abs(0.5 * 0.25 * 2 - 0.25) < 1e-12
    assert math.floor(math.pi * 150 ** 2 / 100) == 706 and abs(1e-14 * 1e9 - 1e-5) < 1e-18
    assert abs(1 / 400e-12 / 1e9 - 2.5) < 1e-9 and 3 * 400 == 1200
    assert abs(1.024 / 1024 * 1e3 - 1) < 1e-12 and abs(6.02 * 12 + 1.76 - 74.0) < 0.01 and abs(1e3 * 100e-15 - 1e-10) < 1e-22
    assert abs(math.exp(-0.1) * 100 - 90.48) < 0.01 and abs(0.5 * 1 * 1 ** 2 - 0.5) < 1e-12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
